async def execute(video_id="", language="en"):
    """Get transcript from a YouTube video.

    Args:
        video_id: YouTube URL or 11-char video ID
        language: Language code (default: 'en')

    Returns:
        JSON with transcript segments and metadata
    """
    import json
    import re
    from youtube_transcript_api import YouTubeTranscriptApi

    if not video_id:
        return json.dumps({"error": "video_id is required"})

    # Extract video ID from URL
    url_patterns = [
        r'(?:youtube\\.com/watch\\?v=|youtu\\.be/|youtube\\.com/shorts/)([a-zA-Z0-9_-]{11})',
        r'^([a-zA-Z0-9_-]{11})$',
    ]
    vid = None
    for pattern in url_patterns:
        m = re.search(pattern, video_id.strip())
        if m:
            vid = m.group(1)
            break

    if not vid:
        return json.dumps({"error": f"Could not extract video ID from '{video_id}'"})

    try:
        api = YouTubeTranscriptApi()
        transcript = api.fetch(vid, languages=[language])
        segments = [
            {"text": seg.text, "start": seg.start, "duration": seg.duration}
            for seg in transcript
        ]
        return json.dumps({
            "video_id": vid,
            "language": language,
            "segment_count": len(segments),
            "segments": segments,
        }, indent=2, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": str(e), "video_id": vid})

async def execute(query="", max_results=10, search_type="video"):
    """Search YouTube for videos or channels.

    Args:
        query: Search query (1-200 chars)
        max_results: Max results (1-50, default 10)
        search_type: "video" or "channel" (default: "video")

    Returns:
        JSON with matching videos/channels and metadata
    """
    import json
    import os
    from googleapiclient.discovery import build

    if not query:
        return json.dumps({"error": "query is required"})

    api_key = os.environ.get('GOOGLE_API_KEY')
    if not api_key:
        return json.dumps({
            "error": "GOOGLE_API_KEY not set — search requires a Google API key with YouTube Data API v3 enabled"
        })

    try:
        youtube = build('youtube', 'v3', developerKey=api_key, cache_discovery=False)
        request = youtube.search().list(
            q=query,
            part='snippet',
            type=search_type,
            maxResults=min(max_results, 50)
        )
        response = request.execute()
        results = []
        for item in response.get('items', []):
            entry = {'type': 'video' if 'videoId' in item['id'] else 'channel'}
            if 'videoId' in item['id']:
                entry['videoId'] = item['id']['videoId']
            if 'channelId' in item['id']:
                entry['channelId'] = item['id']['channelId']
            entry['title'] = item['snippet']['title']
            entry['channelId'] = item['snippet']['channelId']
            entry['channelTitle'] = item['snippet']['channelTitle']
            entry['publishedAt'] = item['snippet']['publishedAt']
            entry['description'] = item['snippet']['description'][:300]
            thumb = item['snippet'].get('thumbnails', {})
            if thumb:
                entry['thumbnail'] = thumb.get('default', {}).get('url', '')
            results.append(entry)

        return json.dumps({
            "query": query,
            "type": search_type,
            "result_count": len(results),
            "results": results,
        }, indent=2, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": f"Search failed: {e}"})

async def execute(channel="", action="latest", limit=10, continuation=""):
    """YouTube channel operations.

    Args:
        channel: @handle, channel URL, or UC... channel ID
        action: "latest" (free, 15 videos via RSS), "videos" (paginated, needs GOOGLE_API_KEY), "resolve" (free, @handle to UC... ID)
        limit: Max results for "videos" action (1-50)
        continuation: Next page token for paginated "videos"

    Returns:
        JSON with channel info and videos
    """
    import json
    import os
    import re

    if action == "resolve":
        api_key = os.environ.get('GOOGLE_API_KEY')
        if not api_key:
            return json.dumps({"error": "GOOGLE_API_KEY required for channel resolve"})
        from googleapiclient.discovery import build
        youtube = build('youtube', 'v3', developerKey=api_key, cache_discovery=False)
        handle = channel.lstrip('@')
        request = youtube.search().list(
            q=f"@{handle}", part='snippet', type='channel', maxResults=1
        )
        response = request.execute()
        items = response.get('items', [])
        if items:
            cid = items[0]['snippet']['channelId']
            return json.dumps({
                "channel_id": cid,
                "title": items[0]['snippet']['title'],
                "resolved_from": channel
            })
        return json.dumps({"error": f"Channel not found: {channel}"})

    if action == "latest":
        import urllib.request
        import xml.etree.ElementTree as ET
        cid = channel
        m = re.search(r'UC[a-zA-Z0-9_-]{22}', channel)
        if m:
            cid = m.group(0)
        else:
            api_key = os.environ.get('GOOGLE_API_KEY')
            if not api_key:
                return json.dumps({"error": "Need GOOGLE_API_KEY to resolve handle, or pass UC... ID directly"})
            from googleapiclient.discovery import build
            youtube = build('youtube', 'v3', developerKey=api_key, cache_discovery=False)
            handle = channel.lstrip('@')
            req = youtube.search().list(q=f"@{handle}", part='snippet', type='channel', maxResults=1)
            resp = req.execute()
            items = resp.get('items', [])
            if not items:
                return json.dumps({"error": f"Channel not found: {channel}"})
            cid = items[0]['snippet']['channelId']
        rss_url = f"https://www.youtube.com/feeds/videos.xml?channel_id={cid}"
        try:
            req = urllib.request.Request(rss_url, headers={'User-Agent': 'Odoo-AI/1.0'})
            with urllib.request.urlopen(req, timeout=10) as resp:
                tree = ET.parse(resp)
            root = tree.getroot()
            ns = {'atom': 'http://www.w3.org/2005/Atom'}
            entries = root.findall('atom:entry', ns)
            videos = []
            for entry in entries[:limit]:
                vid = entry.find('yt:videoId', {'yt': 'http://www.youtube.com/xml/schemas/2015'})
                title = entry.find('atom:title', ns)
                published = entry.find('atom:published', ns)
                author = entry.find('atom:author', ns)
                author_name = author.find('atom:name', ns) if author is not None else None
                link = entry.find('atom:link', ns)
                videos.append({
                    "videoId": vid.text if vid is not None else "",
                    "title": title.text if title is not None else "",
                    "published": published.text if published is not None else "",
                    "author": author_name.text if author_name is not None else "",
                    "link": link.get('href') if link is not None else "",
                })
            return json.dumps({
                "channel_id": cid,
                "result_count": len(videos),
                "results": videos,
            }, indent=2, ensure_ascii=False)
        except Exception as e:
            return json.dumps({"error": f"RSS fetch failed: {e}"})

    if action == "videos":
        api_key = os.environ.get('GOOGLE_API_KEY')
        if not api_key:
            return json.dumps({"error": "GOOGLE_API_KEY required for channel videos listing"})
        from googleapiclient.discovery import build
        youtube = build('youtube', 'v3', developerKey=api_key, cache_discovery=False)
        if continuation:
            request = youtube.search().list(
                part='snippet', type='video', maxResults=min(limit, 50), pageToken=continuation
            )
        else:
            cid = channel
            m = re.search(r'UC[a-zA-Z0-9_-]{22}', channel)
            if m:
                cid = m.group(0)
            else:
                handle = channel.lstrip('@')
                req = youtube.search().list(
                    q=f"@{handle}", part='snippet', type='channel', maxResults=1
                )
                resp = req.execute()
                items = resp.get('items', [])
                if not items:
                    return json.dumps({"error": f"Channel not found: {channel}"})
                cid = items[0]['snippet']['channelId']
            request = youtube.search().list(
                channelId=cid, part='snippet', type='video', order='date', maxResults=min(limit, 50)
            )
        response = request.execute()
        results = []
        for item in response.get('items', []):
            results.append({
                "videoId": item['id']['videoId'],
                "title": item['snippet']['title'],
                "publishedAt": item['snippet']['publishedAt'],
                "description": item['snippet']['description'][:200],
                "thumbnail": item['snippet'].get('thumbnails', {}).get('default', {}).get('url', ''),
            })
        return json.dumps({
            "result_count": len(results),
            "has_more": 'nextPageToken' in response,
            "next_page_token": response.get('nextPageToken', ''),
            "results": results,
        }, indent=2, ensure_ascii=False)

    return json.dumps({"error": f"Unknown action: {action}. Use: latest, videos, resolve"})

async def execute(playlist_id="", max_results=10, continuation=""):
    """Fetch videos from a YouTube playlist.

    Args:
        playlist_id: YouTube playlist URL or ID (PL/UU/LL/FL/OL prefix)
        max_results: Max videos per page (1-50, default 10)
        continuation: Next page token for pagination

    Returns:
        JSON with playlist info and videos
    """
    import json
    import os
    import re

    api_key = os.environ.get('GOOGLE_API_KEY')
    if not api_key:
        return json.dumps({"error": "GOOGLE_API_KEY required for playlist access"})

    if not playlist_id and not continuation:
        return json.dumps({"error": "playlist_id or continuation required"})

    from googleapiclient.discovery import build
    youtube = build('youtube', 'v3', developerKey=api_key, cache_discovery=False)

    pid = playlist_id
    m = re.search(r'(?:list=|/playlist\\?list=)([a-zA-Z0-9_-]+)', playlist_id)
    if m:
        pid = m.group(1)

    try:
        kwargs = {'part': 'snippet', 'maxResults': min(max_results, 50)}
        if pid:
            kwargs['playlistId'] = pid
        if continuation:
            kwargs['pageToken'] = continuation

        request = youtube.playlistItems().list(**kwargs)
        response = request.execute()

        results = []
        for item in response.get('items', []):
            snippet = item['snippet']
            results.append({
                "videoId": snippet['resourceId']['videoId'],
                "title": snippet['title'],
                "position": snippet.get('position', 0),
                "channelId": snippet.get('channelId', ''),
                "channelTitle": snippet.get('channelTitle', ''),
                "publishedAt": snippet.get('publishedAt', ''),
                "description": snippet.get('description', '')[:200],
                "thumbnail": snippet.get('thumbnails', {}).get('default', {}).get('url', ''),
            })

        return json.dumps({
            "playlist_id": pid or "(continuation mode)",
            "result_count": len(results),
            "has_more": 'nextPageToken' in response,
            "next_page_token": response.get('nextPageToken', ''),
            "results": results,
        }, indent=2, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": f"Playlist fetch failed: {e}"})
